SELECT (DATE_TRUNC('HOUR', "LOAD_HOUR")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(QUERY_COUNT)) = 0 OR (SUM(QUERY_COUNT)) IS NULL THEN NULL ELSE CAST((SUM(EXECUTION_MS)) AS DECIMAL(38, 15)) / CAST((SUM(QUERY_COUNT)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "WH_AVG_EXECUTION_MS" FROM (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_TO_TIMESTAMP_NTZ("START_TIME")))) AS LOAD_HOUR, COUNT(*) AS QUERY_COUNT, SUM("QUEUED_OVERLOAD_TIME") AS QUEUED_OVERLOAD_MS, SUM("QUEUED_PROVISIONING_TIME") AS QUEUED_PROVISIONING_MS, SUM("TOTAL_ELAPSED_TIME") AS ELAPSED_MS, SUM("EXECUTION_TIME") AS EXECUTION_MS FROM query_history GROUP BY 1, 2) AS base GROUP BY (DATE_TRUNC('HOUR', "LOAD_HOUR")) ORDER BY "WH_AVG_EXECUTION_MS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
